def canonical_root(items: Mapping[str, str]) -> bytes:
    """Return a deterministic SHA-256 chain root for UTF-8 string pairs."""
    encoded = sorted(
        ((key.encode("utf-8"), value.encode("utf-8"))
         for key, value in items.items()),
        key=lambda pair: pair[0],
    )

    root = hashlib.sha256(b"canonical-dict-v1").digest()
    for key, value in encoded:
        record = (
            len(key).to_bytes(8, "big") + key
            + len(value).to_bytes(8, "big") + value
        )
        root = hashlib.sha256(root + record).digest()
    return root


